effect.shader:
#define iTime (proEvolution + (proAnimate ? acTime * proSpeed : 0.0))
#define iResolution vec3(acLayerSize, 1.0)
#define iDate vec4(0.0, 0.0, 0.0, iTime)
#define iMouse vec4(acLayerSize * 0.5, 0.0, 0.0)
#define PI 3.14159265359
float smin(float a,float b,float k){
float h=clamp(.5+.5*(a-b)/k,0.,1.);
return mix(a,b,h)-k*h*(1.-h);
}
float smax(float a,float b,float k){
return smin(a,b,-k);
}
float softRelu(float x){
return log(.8+exp(min(1.,100.*x)))*.01;
}
float softLength(vec2 x){
float len = length(x);
return len +0.0009/(len+0.03);
}
float sdRoundBox2D(vec2 p,vec2 b,float r){
vec2 q=abs(p)-b;
return .3*(softLength(max(q,0.))+min(smax(q.x,q.y,1.),0.)-r);
}
float sdCircle(vec2 p,float r){
return .3*(softLength(p)-r);
}
float sceneSDF(vec2 p,vec2 mouse,float k){
float dBox=sdRoundBox2D(p+vec2(.3,0)*sin(iTime),vec2(.1,.02),.2);
float dPanel=sdRoundBox2D(p-mouse,vec2(proWidth,proHeight)*0.5,proCorner);
float d=softRelu(smin(dBox,dPanel,k))*proShapeGain;
return d;
}
vec2 refractOffset(vec2 n2,float eta,float thick){
vec3 N=normalize(vec3(-n2,1.));
vec3 I=vec3(0.,0.,-1.);
vec3 R=refract(I,N,1./eta);
float z=max(abs(R.z),1e-5);
return-thick*(R.xy/z);
}
float fresnel_schlick(float cosTheta,float F0){
return F0+(1.-F0)*pow(1.-cosTheta,5.);
}
float reflectionTerm(float d,vec2 n2,float gain){
vec3 N=normalize(vec3(-n2,1.));
vec3 V=vec3(0.,0.,1.);
float NoV=clamp(dot(N,V),0.,1.);
float F=fresnel_schlick(NoV,.06);
float rim=pow(1.-NoV,3.);
float inside=smoothstep(proEdgeSoftness,-proEdgeSoftness,d);
float inten=(F+.5*rim)*gain*inside;
return inten;
}
float jacobian(vec2 uv,vec2 duv){
float focus=1.0+length(duv)*proCausticGain;
vec2 bx=vec2(1.0,0.0),by=vec2(0.0,1.0);
float detB=1.0;
vec2 ux=vec2(1.0,0.0),uy=vec2(0.0,1.0);
float detU=1.0;
return clamp(focus,0.8,5.0);
}
#define SMIN_K proSmoothUnion
#define REFRACTIVE vec3(proIorR,proIorG,proIorB)
#define THICKNESS proThickness
#define REFL_GAIN proReflection
#define DISTANCE_TO_NORMAL_FACTOR proNormalStrength
vec4 tex(vec2 uv){
return texture2DCv(inputImg.texture,uv);
}
void gmGeneratedMainImage(out vec4 fragColor,in vec2 fragCoord){
vec2 R=iResolution.xy;
vec2 uv=fragCoord/R;
vec2 p=(fragCoord-.5*R)/R.y;
vec2 m=(vec2(proCenterX,proCenterY)*R-.5*R)/R.y;
float d=sceneSDF(p,m,SMIN_K);
vec2 pe=vec2(2.0/max(R.y,1.0),0.0); vec2 n2=vec2(sceneSDF(p+pe.xy,m,SMIN_K)-sceneSDF(p-pe.xy,m,SMIN_K),sceneSDF(p+pe.yx,m,SMIN_K)-sceneSDF(p-pe.yx,m,SMIN_K))/(2.0*pe.x)*DISTANCE_TO_NORMAL_FACTOR;
float thick= THICKNESS*(clamp(-30.*d,0.,1.));
float inside=smoothstep(proEdgeSoftness,-proEdgeSoftness,d);
vec2 duvR=refractOffset(n2,REFRACTIVE.r,thick)*inside;
vec2 duvG=refractOffset(n2,REFRACTIVE.g,thick)*inside;
vec2 duvB=refractOffset(n2,REFRACTIVE.b,thick)*inside;
float r=tex(uv+duvR).r*jacobian(uv,duvR);
float g=tex(uv+duvG).g*jacobian(uv,duvG);
float b=tex(uv+duvB).b*jacobian(uv,duvB);
vec3 bg=vec3(r,g,b);
vec3 refl=vec3(1)*reflectionTerm(d,n2,REFL_GAIN);
vec3 col=bg+refl;
col+=inside*.02*pow(abs(dot(n2,normalize(vec2(1.5,1.)))),3.);
fragColor=vec4(col,1.);
}
void main(){
vec4 gmGenerated=vec4(0.0);
gmGeneratedMainImage(gmGenerated,acLayerNorm*acLayerSize);
vec4 gmSource=texture2DCv(inputImg.texture,acLayerNorm);
float gmAlpha=gmClip?gmSource.a:gmGenerated.a;
vec4 gmResult=vec4(gmGenerated.rgb*gmAlpha,gmAlpha);
gl_FragColor=mix(gmSource,gmResult,gmMix);
}
